/** Shared layout for plugin data tables, based on the employee directory. */
export const tablePanelClass =
  "min-w-0 rounded-xl border border-border bg-card p-6 text-card-foreground";
export const tableClass =
  "w-full min-w-[36rem] border-separate border-spacing-0 caption-bottom text-sm";
export const tableHeaderClass = "h-10 px-2 text-left align-middle font-medium whitespace-nowrap";
export const tableRowClass =
  "group border-b border-border hover:bg-muted/50 [&>*]:[border-bottom:inherit]";
export const tableCellClass = "p-2 align-middle";
export const tableActionCellClass =
  "w-px p-2 text-right align-middle whitespace-nowrap sticky right-0 z-10 bg-card backdrop-blur-sm group-hover:bg-muted supports-[backdrop-filter]:bg-card/80 supports-[backdrop-filter]:group-hover:bg-muted/80";
export const tableActionHeaderClass = `${tableActionCellClass} h-10 font-medium`;
export const tableActionsClass = "flex items-center justify-end gap-2";
export const tableFooterClass = "mt-5 flex flex-wrap items-center justify-end gap-3";

export const tablePageClass = "mx-auto w-full max-w-7xl space-y-6 px-4 py-8 sm:px-6";

import { cn } from "@/components/utils/cn";

export const buttonClass =
  "inline-flex min-h-10 items-center justify-center gap-2 rounded-md px-3 text-sm font-medium transition-colors md:min-h-8 text-foreground outline-none hover:bg-accent hover:text-accent-foreground focus-visible:ring-2 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 disabled:bg-background disabled:text-foreground disabled:hover:bg-background disabled:hover:text-foreground dark:disabled:bg-background dark:disabled:hover:bg-background [&_svg]:size-4 cursor-pointer disabled:cursor-not-allowed aria-disabled:cursor-not-allowed data-disabled:cursor-not-allowed";
export const primaryClass = cn(
  buttonClass,
  "bg-primary text-primary-foreground hover:bg-primary/90 hover:text-primary-foreground",
);
export const outlineButtonClass = cn(buttonClass, "border border-border");
export const iconButtonClass = cn(
  buttonClass,
  "size-10 min-h-10 shrink-0 border border-border bg-background p-0 disabled:pointer-events-auto md:size-8 md:min-h-8",
);
